CustomField.formula:
if(
    AND( CAP_Complete__c , IMGA__c, NOT(ISBLANK(IMGA_Risk_Assessment__r.At_Risk_Override_Date__c))),
    text(
        month(
            IMGA_Risk_Assessment__r.At_Risk_Override_Date__c
        )
    ) & '/' & text(
        day(
            IMGA_Risk_Assessment__r.At_Risk_Override_Date__c
        )
    ) & '/' & text(
        year(
            IMGA_Risk_Assessment__r.At_Risk_Override_Date__c
        )
    ),
    'N/A'
)
